mapper.select:
SELECT id, notification_type as notificationType, title, message, is_read as isRead, created_at as createdAt, url
FROM notifications
WHERE user_id = #{userId}
  AND is_deleted = 0
  AND DATE(created_at) <= #{asOfDate}
ORDER BY created_at DESC

mapper.update:
UPDATE notifications
SET is_read = TRUE
WHERE user_id = #{userId} AND id = #{id}
